Code:
set_fflags_platform(struct archive_write_disk *a, int fd, const char *name,
    mode_t mode, unsigned long set, unsigned long clear)
{
	int		 ret;
	int		 myfd = fd;
	int newflags, oldflags;
	/*
	 * Linux has no define for the flags that are only settable by
	 * the root user.  This code may seem a little complex, but
	 * there seem to be some Linux systems that lack these
	 * defines. (?)  The code below degrades reasonably gracefully
	 * if sf_mask is incomplete.
	 */
	const int sf_mask = 0
#if defined(FS_IMMUTABLE_FL)
	    | FS_IMMUTABLE_FL
#elif defined(EXT2_IMMUTABLE_FL)
	    | EXT2_IMMUTABLE_FL
#endif
#if defined(FS_APPEND_FL)
	    | FS_APPEND_FL
#elif defined(EXT2_APPEND_FL)
	    | EXT2_APPEND_FL
#endif
#if defined(FS_JOURNAL_DATA_FL)
	    | FS_JOURNAL_DATA_FL
#endif
	;

	if (set == 0 && clear == 0)
		return (ARCHIVE_OK);
	/* Only regular files and dirs can have flags. */
	if (!S_ISREG(mode) && !S_ISDIR(mode))
		return (ARCHIVE_OK);

	/* If we weren't given an fd, open it ourselves. */
	if (myfd < 0) {
		myfd = open(name, O_RDONLY | O_NONBLOCK | O_BINARY |
		    O_CLOEXEC | O_NOFOLLOW);
		__archive_ensure_cloexec_flag(myfd);
	}
	if (myfd < 0)
		return (ARCHIVE_OK);

	/*
	 * XXX As above, this would be way simpler if we didn't have
	 * to read the current flags from disk. XXX
	 */
	ret = ARCHIVE_OK;

	/* Read the current file flags. */
	if (ioctl(myfd,
#ifdef FS_IOC_GETFLAGS
	    FS_IOC_GETFLAGS,
#else
	    EXT2_IOC_GETFLAGS,
#endif
	    &oldflags) < 0)
		goto fail;

	/* Try setting the flags as given. */
	newflags = (oldflags & ~clear) | set;
	if (ioctl(myfd,
#ifdef FS_IOC_SETFLAGS
	    FS_IOC_SETFLAGS,
#else
	    EXT2_IOC_SETFLAGS,
#endif
	    &newflags) >= 0)
		goto cleanup;
	if (errno != EPERM)
		goto fail;

	/* If we couldn't set all the flags, try again with a subset. */
	newflags &= ~sf_mask;
	oldflags &= sf_mask;
	newflags |= oldflags;
	if (ioctl(myfd,
#ifdef FS_IOC_SETFLAGS
	    FS_IOC_SETFLAGS,
#else
	    EXT2_IOC_SETFLAGS,
#endif
	    &newflags) >= 0)
		goto cleanup;

	/* We couldn't set the flags, so report the failure. */
fail:
	archive_set_error(&a->archive, errno,
	    "Failed to set file flags");
	ret = ARCHIVE_WARN;
cleanup:
	if (fd < 0)
		close(myfd);
	return (ret);
}

raw_output:
1. Sequence: if no flags are requested, the function returns OK. If `mode` is neither regular nor directory, it returns OK. Otherwise it uses or opens a descriptor, reads existing flags, applies `set` and `clear`, and issues `FS_IOC_SETFLAGS`/`EXT2_IOC_SETFLAGS`.
2. Branch: on a failed first set, execution continues only for `EPERM`; it then strips root-only bits from the requested change and preserves the current root-only bits for a second attempt.
3. Branch: the descriptor is closed only when the original caller supplied `fd < 0`, so caller-owned descriptors are not closed.
4. Loop: there is no iteration; at most two `SETFLAGS` attempts occur.
5. Branch: `sf_mask` is a recovery mask, not an allowlist. If the process is privileged, externally supplied archive metadata can directly set dangerous root-only flags such as immutable, append-only, or journal-data flags.
6. Branch: the regular-file/directory decision is based on caller-supplied `mode`, not on an `fstat()` of `myfd`; a mismatched descriptor can therefore be passed to filesystem-specific ioctl handling.
7. Branch: when `fd < 0`, `name` is passed directly to `open()` without a NULL check, causing undefined behavior if `name` is NULL. `O_NOFOLLOW` protects only the final path component, not intermediate traversal.
8. Cleanup/fd lifetime is otherwise consistent: the helper closes only descriptors it opened.

